CREATE TRIGGER provider_mapping_no_delete BEFORE DELETE ON provider_team_mappings BEGIN SELECT RAISE(ABORT,'provider_mapping_immutable'); END;
CREATE TRIGGER provider_enrichment_no_delete BEFORE DELETE ON provider_enrichment_observations BEGIN SELECT RAISE(ABORT,'provider_enrichment_immutable'); END;
CREATE TRIGGER live_feature_no_delete BEFORE DELETE ON live_feature_snapshots BEGIN SELECT RAISE(ABORT,'live_feature_immutable'); END;
CREATE TRIGGER live_detail_no_delete BEFORE DELETE ON live_match_details BEGIN SELECT RAISE(ABORT,'live_detail_immutable'); END;
CREATE TRIGGER live_report_no_delete BEFORE DELETE ON live_daily_reports BEGIN SELECT RAISE(ABORT,'live_report_immutable'); END;
CREATE TRIGGER live_evaluation_no_delete BEFORE DELETE ON live_evaluation_revisions BEGIN SELECT RAISE(ABORT,'live_evaluation_immutable'); END;
CREATE TRIGGER live_prediction_source_guard BEFORE INSERT ON live_prediction_snapshots WHEN NOT EXISTS(SELECT 1 FROM provider_fixture_observations o JOIN live_feature_snapshots f ON f.id=NEW.feature_id WHERE o.id=NEW.observation_id AND o.fixture_id=NEW.fixture_id AND o.occurrence_id=NEW.occurrence_id AND o.kickoff_utc=NEW.kickoff_utc AND o.observed_at<=NEW.generated_at AND f.fixture_id=NEW.fixture_id AND f.available_at<=NEW.generated_at AND f.cutoff_date<=json_extract(o.payload,'$.date')) BEGIN SELECT RAISE(ABORT,'live_prediction_temporal_or_source_mismatch'); END;
CREATE TRIGGER live_prediction_probability_guard BEFORE INSERT ON live_prediction_snapshots WHEN json_array_length(NEW.payload,'$.probabilities')<>3 OR abs((SELECT sum(value) FROM json_each(NEW.payload,'$.probabilities'))-1)>0.000001 OR EXISTS(SELECT 1 FROM json_each(NEW.payload,'$.probabilities') WHERE type NOT IN('real','integer') OR value<0 OR value>1) BEGIN SELECT RAISE(ABORT,'invalid_live_probabilities'); END;
